#include "unity.h"
#include "header.h"
#include "helpers.h"
#include "malloc_wrap.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_push_full_stack_double_array_fails(void) {
    /* Path 2: ptr != NULL, stack is full (ptr->top == capacity-1),
     * double_array returns NULL (result == NULL) -> return -1
     * Need to create a stack, fill it to capacity, then cause double_array to fail.
     * create_stack makes 2 allocations (struct + array).
     * double_array will attempt a malloc for the new array.
     * We need the first 2 allocations (setup) to succeed, then fail the 3rd (inside double_array).
     */
    DArrayStack *stack = NULL;
    int capacity = 5;
    int data = 42;
    int i;
    int ret;

    /* Create a stack with capacity 5 */
    stack = create_stack(capacity);
    TEST_ASSERT_NOT_NULL(stack);
    /* Fill it to capacity (top from -1 to 4) */
    for (i = 0; i < capacity; i++) {
        ret = push(stack, i * 10);
        TEST_ASSERT_EQUAL_INT(i, ret); /* top index after each push */
    }
    /* Now stack is full: top == capacity-1 == 4 */

    /* Cause the next malloc (inside double_array) to fail.
     * Two allocations already happened (create_stack).
     * Use malloc_fail_after(2) to fail the 3rd allocation.
     */
    malloc_fail_after(2);

    /* Attempt to push another element. Stack is full, so double_array will be called.
     * double_array will attempt to malloc a new array of size 2*capacity.
     * That malloc will fail (NULL), so push should return -1.
     */
    ret = push(stack, data);
    TEST_ASSERT_EQUAL_INT(-1, ret);
    /* Clean up stack after failed push */
    free_stack(stack);

    /* Verify stack state unchanged (still full, same capacity) */
    /* Note: Cannot verify after free_stack - stack is now freed */
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_push_full_stack_double_array_fails);
    return UNITY_END();
}

